using System;class RatingsTests {static void Check(bool expected,string mode,bool menu,string role,string name){bool got=MurglarPolicy.RatingMatch(mode,menu,role,name);if(got!=expected)throw new Exception("FAIL rating match "+mode+" "+name);}public static int Main(){Check(true,"--like",false,"push button","Добавить себе");Check(true,"--like",false,"push button","Удалить из своих");Check(true,"--like",false,"push button","Like");Check(false,"--like",false,"label","Добавить себе");Check(false,"--like",false,"push button","Don't recommend");Check(true,"--dislike",false,"push button","Don't recommend");Check(true,"--dislike",true,"label","Не рекомендовать трек");Check(true,"--dislike",true,"label","Don't recommend track");Check(false,"--dislike",true,"label","Не рекомендовать исполнителя");Check(false,"--dislike",true,"label","Don't recommend artist");Check(false,"--dislike",true,"push button","Don't recommend");Check(false,"--invalid",true,"label","Не рекомендовать трек");Console.WriteLine("PASS: like toggle states, exact track-only menu, artist exclusion, role and mode guards");return 0;}}
